const oldState = $('Read account state').item.json;
const reReg = $('Re-register watch()').item.json;

const oldLastSuccessfulSync = oldState.last_successful_sync || null;
// Gmail's messages.list `after:` search operator accepts a Unix timestamp in seconds.
const afterEpochSeconds = oldLastSuccessfulSync
  ? Math.floor(new Date(oldLastSuccessfulSync).getTime() / 1000)
  : 0;

return [{
  json: {
    accountId: oldState.id,
    oldSyncCursor: oldState.sync_cursor,
    oldLastSuccessfulSync,
    afterEpochSeconds,
    newSubscriptionId: 'projects/REPLACE_WITH_GCP_PROJECT_ID/topics/gmail-push-notifications',
    newHistoryId: reReg.historyId,
    newExpiration: reReg.expiration,
  },
}];

const input = $input.first().json;
let ids = [];

if (Array.isArray(input.history)) {
  // history.list response
  for (const h of input.history) {
    for (const added of h.messagesAdded || []) {
      if (added.message && added.message.id) ids.push(added.message.id);
    }
  }
} else if (Array.isArray(input.messages)) {
  // messages.list fallback response
  for (const m of input.messages) {
    if (m.id) ids.push(m.id);
  }
}

ids = [...new Set(ids)];
return ids.map((id) => ({ json: { id } }));
